/* @lc app=leetcode id=1488 lang=kotlin */ class Solution { fun avoidFlood(rains: IntArray): IntArray = java.util.TreeSet<Int>().let { dry -> HashMap<Int, Int>().let { last -> IntArray(rains.size) { if (rains[it] > 0) -1 else 1 }.let { ans -> rains.indices.all { i -> if (rains[i] == 0) dry.add(i).let { true } else (last.put(rains[i], i)?.let { j -> dry.higher(j)?.also { d -> dry.remove(d) }?.also { d -> ans[d] = rains[i] } != null } ?: true) }.let { ok -> if (ok) ans else intArrayOf() } } } } }